// A video split into parts by stream copy (#1259): the command line and where the parts begin (no FFmpeg needed), and
// real splits through the job queue, which run only when FFmpeg is installed (`pwsh build/fetch-engines.ps1 -Only
// ffmpeg`). Inputs are generated by FFmpeg itself and every part is checked with ffprobe.

using System.Globalization;
using System.Text.Json;
using Filee.Core.Conversion;
using Filee.Core.Presets;
using Filee.Engines.Infrastructure;
using Filee.Engines.Media;

namespace Filee.Engines.Tests;

[Collection(nameof(FfmpegCollection))]
public class VideoSplitTests(EngineFixture fx) : IClassFixture<EngineFixture>
{
    private static readonly (string Ffmpeg, string Ffprobe)? Tools = FfmpegConverter.Locate();

    private static void SkipUnlessInstalled() =>
        Assert.SkipUnless(Tools is not null, "FFmpeg is not installed (pwsh build/fetch-engines.ps1 -Only ffmpeg)");

    // ───────────────────────── Command lines (no FFmpeg needed) ─────────────────────────

    private static readonly VideoStreamInfo Hd = new(1920, 1080, 1, 0, 29.97, "h264", "yuv420p");
    private static readonly MediaInfo Movie = new(TimeSpan.FromMinutes(10), Hd, new AudioStreamInfo(2, 48000, "aac"), null);

    private static string After(IReadOnlyList<string> args, string option) => args[args.ToList().IndexOf(option) + 1];

    [Fact]
    public void A_split_copies_the_streams_into_the_segment_muxer()
    {
        var args = MediaEncoding.SplitCopy("in.mp4", "part%04d.mp4", "mp4", new MediaOptions { SplitEverySeconds = 180 }, Movie);

        Assert.Equal("copy", After(args, "-c"));
        Assert.DoesNotContain("-c:v", args);
        Assert.DoesNotContain("-ss", args);
        Assert.Equal(["0:V:0", "0:a:0"], args.Where((a, i) => i > 0 && args[i - 1] == "-map"));
        Assert.Equal("segment", After(args, "-f"));
        Assert.Equal("mp4", After(args, "-segment_format"));
        Assert.Equal("180.000,360.000,540.000", After(args, "-segment_times"));
        Assert.Equal("1", After(args, "-reset_timestamps"));
        // The MP4's own option goes to each part: the segment muxer has no -movflags.
        Assert.Equal("movflags=+faststart", After(args, "-segment_format_options"));
        Assert.DoesNotContain("-movflags", args);
        Assert.Equal("part%04d.mp4", args[^1]);
    }

    [Fact]
    public void A_split_keeps_what_a_fast_clip_keeps()
    {
        var hevc = Movie with { Video = Hd with { Codec = "hevc" }, Audio = new AudioStreamInfo(2, 48000, "aac", 1) };
        var args = MediaEncoding.SplitCopy("in.mov", "part%04d.mov", "mov", new MediaOptions { SplitParts = 2 }, hevc);
        Assert.Equal("hvc1", After(args, "-tag:v"));
        Assert.Equal(["0:V:0", "0:a:1"], args.Where((a, i) => i > 0 && args[i - 1] == "-map"));

        var silent = MediaEncoding.SplitCopy("in.mkv", "part%04d.mkv", "mkv", new MediaOptions { SplitParts = 2, RemoveAudio = true }, Movie);
        Assert.Contains("-an", silent);
        Assert.Equal("matroska", After(silent, "-segment_format"));
        // Matroska has no options of its own.
        Assert.DoesNotContain("-segment_format_options", silent);
        Assert.Equal("mpegts_m2ts_mode=1", MediaEncoding.SegmentFormatOptions("m2ts"));
        Assert.Equal("muxrate=10080000:packetsize=2048", MediaEncoding.SegmentFormatOptions("vob"));

        Assert.Throws<InvalidOperationException>(() =>
            MediaEncoding.SplitCopy("in.mp4", "p%04d.mp4", "mp4", new MediaOptions { SplitParts = 2 }, Movie with { Video = null }));
        Assert.Throws<NotSupportedException>(() =>
            MediaEncoding.SplitCopy("in.rm", "p%04d.rm", "rm", new MediaOptions { SplitParts = 2 }, Movie));
    }

    [Theory]
    // Every 3 minutes of 10: parts begin at 3, 6 and 9 (four parts, the last one minute).
    [InlineData(180, 0, 600, new[] { 180.0, 360, 540 })]
    // Every 5 minutes of exactly 10: two parts, no empty third.
    [InlineData(300, 0, 600, new[] { 300.0 })]
    // A point in the last second would only make a part of the last frames.
    [InlineData(300, 0, 600.5, new[] { 300.0 })]
    [InlineData(300, 0, 601.5, new[] { 300.0, 600 })]
    // Shorter than one part: one file.
    [InlineData(600, 0, 90, new double[0])]
    // Thirds of 10 minutes; halves of 75 seconds.
    [InlineData(0, 3, 600, new[] { 200.0, 400 })]
    [InlineData(0, 2, 75, new[] { 37.5 })]
    // Equal parts win over seconds, as SplitParts says.
    [InlineData(60, 2, 600, new[] { 300.0 })]
    public void The_parts_begin_every_so_often_or_at_equal_lengths(int every, int parts, double duration, double[] expected)
    {
        var points = MediaEncoding.SplitPoints(new MediaOptions { SplitEverySeconds = every, SplitParts = parts }, duration);
        Assert.Equal(expected, points!);
    }

    [Fact]
    public void A_split_without_a_length_goes_by_seconds_or_is_refused()
    {
        // A raw stream has no length: FFmpeg counts the seconds itself.
        Assert.Null(MediaEncoding.SplitPoints(new MediaOptions { SplitEverySeconds = 60 }, null));
        var raw = MediaEncoding.SplitCopy("in.ts", "part%04d.ts", "ts", new MediaOptions { SplitEverySeconds = 60 }, Movie with { Duration = null });
        Assert.Equal("60", After(raw, "-segment_time"));
        Assert.DoesNotContain("-segment_times", raw);

        // Equal parts of an unknown length can't be measured.
        var unknown = Assert.Throws<ConversionRefusedException>(() => MediaEncoding.SplitPoints(new MediaOptions { SplitParts = 3 }, null));
        Assert.Equal("error.split_unknown_length", unknown.ErrorKey);
    }

    [Fact]
    public void Too_many_parts_are_refused_before_anything_is_written()
    {
        // Two hours every second: 7,200 files.
        var every = Assert.Throws<ConversionRefusedException>(() =>
            MediaEncoding.SplitPoints(new MediaOptions { SplitEverySeconds = 1 }, 7200));
        Assert.Equal("error.too_many_parts", every.ErrorKey);
        var parts = Assert.Throws<ConversionRefusedException>(() =>
            MediaEncoding.SplitPoints(new MediaOptions { SplitParts = MediaOptions.MaxSplitParts + 1 }, 7200));
        Assert.Equal("error.too_many_parts", parts.ErrorKey);
        // Exactly the most is fine.
        Assert.Equal(MediaOptions.MaxSplitParts - 1,
            MediaEncoding.SplitPoints(new MediaOptions { SplitEverySeconds = 10 }, MediaOptions.MaxSplitParts * 10)!.Count);
    }

    [Fact]
    public void A_split_is_refused_where_the_streams_cant_be_copied()
    {
        // H.264 and AAC go into MP4, MOV and MKV as they are, not into WebM.
        Assert.True(MediaEncoding.SplitTakes("mp4", Movie, new MediaOptions()));
        Assert.True(MediaEncoding.SplitTakes("mkv", Movie, new MediaOptions()));
        Assert.False(MediaEncoding.SplitTakes("webm", Movie, new MediaOptions()));
        // The sound counts only when it is kept.
        var opus = Movie with { Audio = new AudioStreamInfo(2, 48000, "opus") };
        Assert.False(MediaEncoding.SplitTakes("mp4", opus, new MediaOptions()));
        Assert.True(MediaEncoding.SplitTakes("mp4", opus, new MediaOptions { RemoveAudio = true }));
        Assert.True(MediaEncoding.SplitTakes("mp4", Movie with { Audio = null }, new MediaOptions()));
        // Containers Filee doesn't list are left to FFmpeg.
        Assert.True(MediaEncoding.SplitTakes("avi", Movie, new MediaOptions()));
    }

    [Theory]
    [InlineData(1, 3, "_part1")]
    [InlineData(3, 9, "_part3")]
    [InlineData(4, 12, "_part04")]
    [InlineData(120, 120, "_part120")]
    public void Parts_are_numbered_so_they_sort_in_order(int number, int count, string suffix) =>
        Assert.Equal(suffix, FfmpegConverter.PartSuffix(number, count.ToString(CultureInfo.InvariantCulture).Length));

    [Fact]
    public void Only_a_video_made_into_a_video_is_split()
    {
        var preset = new Preset { TargetFormat = "mp4", Media = { SplitParts = 2 } };
        Assert.True(preset.SplitsVideoOf("mkv"));
        Assert.False(preset.SplitsVideoOf("mp3"));
        Assert.False(preset.SplitsVideoOf("png"));
        Assert.False(new Preset { TargetFormat = "mp3", Media = { SplitParts = 2 } }.SplitsVideoOf("mp4"));
        Assert.False(new Preset { TargetFormat = "mp4" }.SplitsVideoOf("mp4"));
        // A crop or a join makes one file of its own.
        Assert.False(new Preset { TargetFormat = "mp4", Media = { SplitParts = 2, CropFrame = "1:1" } }.SplitsVideoOf("mp4"));
        Assert.False(new Preset { TargetFormat = "mp4", Media = { SplitParts = 2, JoinIntoOne = true } }.SplitsVideoOf("mp4"));
    }

    // ───────────────────────── Real splits (FFmpeg needed) ─────────────────────────

    /// <summary>A 10-second test video (moving pattern and a tone) with a key frame every second.</summary>
    private static async Task<string> MakeVideoAsync(string folder, string name)
    {
        var path = Path.Combine(folder, name);
        List<string> args =
        [
            "-hide_banner", "-nostdin", "-v", "error", "-y",
            "-f", "lavfi", "-i", "testsrc2=size=320x240:rate=25:duration=10",
            "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000:duration=10", "-ac", "2",
            "-c:v", "libx264", "-g", "25", "-pix_fmt", "yuv420p", "-c:a", "aac",
            path,
        ];
        var result = await ProcessRunner.RunAsync(Tools!.Value.Ffmpeg, args, TimeSpan.FromMinutes(2), CancellationToken.None);
        Assert.True(result.ExitCode == 0, result.StandardError);
        return path;
    }

    private static async Task<(double Duration, string? VideoCodec, string? AudioCodec)> ProbeAsync(string path)
    {
        var result = await ProcessRunner.RunAsync(Tools!.Value.Ffprobe,
            ["-v", "error", "-print_format", "json", "-show_format", "-show_streams", path], TimeSpan.FromMinutes(1), CancellationToken.None);
        Assert.True(result.ExitCode == 0, $"ffprobe {path}: {result.StandardError}");
        using var json = JsonDocument.Parse(result.StandardOutput);
        var streams = json.RootElement.GetProperty("streams").EnumerateArray().ToList();
        string? Codec(string type) => streams.FirstOrDefault(s => s.GetProperty("codec_type").GetString() == type) is { ValueKind: JsonValueKind.Object } s
            ? s.GetProperty("codec_name").GetString() : null;
        var duration = double.Parse(json.RootElement.GetProperty("format").GetProperty("duration").GetString()!, CultureInfo.InvariantCulture);
        return (duration, Codec("video"), Codec("audio"));
    }

    private async Task<List<string>> SplitAsync(string source, string target, MediaOptions media)
    {
        var job = await fx.ConvertAsync([source], new Preset { TargetFormat = target, Media = media });
        Assert.True(job.State == JobState.Completed, string.Join("; ", job.Files.Select(f => $"{f.ErrorKey} {f.ErrorDetail}")));
        return [.. job.Outputs];
    }

    [Fact]
    public async Task A_video_is_copied_into_parts_every_so_many_seconds_next_to_it()
    {
        SkipUnlessInstalled();
        var folder = fx.NewFolder();
        var source = await MakeVideoAsync(folder, "match.mp4");

        var outputs = await SplitAsync(source, "mp4", new MediaOptions { SplitEverySeconds = 4 });

        Assert.Equal(["match_part1.mp4", "match_part2.mp4", "match_part3.mp4"], outputs.Select(Path.GetFileName).Order());
        var probed = new List<(double Duration, string? VideoCodec, string? AudioCodec)>();
        foreach (var output in outputs.Order())
            probed.Add(await ProbeAsync(output));
        // Copied, not encoded: the same codecs, each part starting at a key frame, together the whole video.
        Assert.All(probed, p => Assert.Equal(("h264", "aac"), (p.VideoCodec, p.AudioCodec)));
        Assert.InRange(probed[0].Duration, 3.9, 4.2);
        Assert.InRange(probed[1].Duration, 3.9, 4.2);
        Assert.InRange(probed.Sum(p => p.Duration), 9.8, 10.4);
        // Nothing else is left beside the video.
        Assert.Equal(4, Directory.GetFiles(folder).Length);
    }

    [Fact]
    public async Task A_video_is_copied_into_equal_parts_in_another_container()
    {
        SkipUnlessInstalled();
        var source = await MakeVideoAsync(fx.NewFolder(), "match.mp4");

        var outputs = await SplitAsync(source, "mkv", new MediaOptions { SplitParts = 2 });

        Assert.Equal(["match_part1.mkv", "match_part2.mkv"], outputs.Select(Path.GetFileName).Order());
        foreach (var output in outputs)
        {
            var (duration, video, audio) = await ProbeAsync(output);
            Assert.Equal(("h264", "aac"), (video, audio));
            Assert.InRange(duration, 4.8, 5.3);
        }
    }

    [Fact]
    public async Task Existing_parts_are_kept_and_the_new_ones_numbered()
    {
        SkipUnlessInstalled();
        var source = await MakeVideoAsync(fx.NewFolder(), "match.mp4");
        var first = await SplitAsync(source, "mp4", new MediaOptions { SplitParts = 2 });
        var second = await SplitAsync(source, "mp4", new MediaOptions { SplitParts = 2 });
        Assert.Empty(first.Intersect(second));
        Assert.All(first.Concat(second), path => Assert.True(File.Exists(path)));
    }

    [Fact]
    public async Task A_split_the_target_cant_hold_is_refused_and_leaves_nothing_behind()
    {
        SkipUnlessInstalled();
        var folder = fx.NewFolder();
        // H.264 can't go into WebM as it is, and a split never encodes.
        var source = await MakeVideoAsync(folder, "match.mp4");

        var job = await fx.ConvertAsync([source], new Preset { TargetFormat = "webm", Media = { SplitParts = 2 } });

        Assert.Equal(JobState.Failed, job.State);
        Assert.Equal("error.split_needs_copy", Assert.Single(job.Files).ErrorKey);
        Assert.Equal(["match.mp4"], Directory.GetFiles(folder).Select(Path.GetFileName));
    }
}
